import JSON

"""
	gen( p, k, lambda, name )

Generate fixture data and write to file.

The quantile is evaluated in extended precision from the textbook formula `lambda * (-ln(1-p))^(1/k)`, as forming `1-p` in double precision rounds away the low-order bits of `p` (all of them for `p < 2^-53`).

# Arguments

* `p`: input value
* `k`: shape parameter
* `lambda`: scale parameter
* `name::AbstractString`: output filename

# Examples

``` julia
julia> p = rand( 1000 );
julia> lambda = rand( 1000 ) .* 20.0;
julia> k = ( rand( 1000 ) .* 10.0 ) .+ 10.0;
julia> gen( p, k, lambda, "data.json" );
```
"""
function gen( p, k, lambda, name )
	z = setprecision( BigFloat, 2048 ) do
		Float64.( BigFloat.( lambda ) .* ( .-log.( 1 .- BigFloat.( p ) ) ) .^ ( 1 ./ BigFloat.( k ) ) )
	end

	# Store data to be written to file as a collection:
	data = Dict([
		("p", p),
		("lambda", lambda),
		("k", k),
		("expected", z)
	]);

	# Based on the script directory, create an output filepath:
	filepath = joinpath( dir, name );

	# Write the data to the output filepath as JSON:
	outfile = open( filepath, "w" );
	write( outfile, JSON.json(data) );
	write( outfile, "\n" );
	close( outfile );
end

# Get the filename:
file = @__FILE__;

# Extract the directory in which this file resides:
dir = dirname( file );

# Large scale parameter:
p = rand( 1000 );
lambda = ( rand( 1000 ) .* 10.0 ) .+ 10.0;
k = rand( 1000 ) .* 10.0;
gen( p, k, lambda, "large_scale.json" );

# Large shape parameter:
p = rand( 1000 );
lambda = rand( 1000 ) .* 10.0;
k = ( rand( 1000 ) .* 10.0 ) .+ 10.0;
gen( p, k, lambda, "large_shape.json" );

# Both large:
p = rand( 1000 );
lambda = ( rand( 1000 ) .* 20.0 ) .+ 10.0;
k = ( rand( 1000 ) .* 20.0 ) .+ 10.0;
gen( p, k, lambda, "both_large.json" );

# Small `p` (shape parameters are powers of two, so that `1/k` is exact and the test measures the error from `1-p`):
p = exp10.( range( -300.0, stop = -1.0, length = 1000 ) );
lambda = ( rand( 1000 ) .* 10.0 ) .+ 0.1;
k = repeat( [ 1.0, 2.0, 4.0, 8.0 ], 250 );
gen( p, k, lambda, "small_p.json" );
